"""Number base conversion utilities."""


def _check_base(base):
    if not isinstance(base, int) or isinstance(base, bool):
        raise ValueError("base must be an integer")
    if base < 2 or base > 36:
        raise ValueError("base must be between 2 and 36")


def to_base(number, base):
    """Return the int ``number`` written in ``base`` (2 to 36).

    Digits are 0-9 then lower-case a-z. Zero is "0". Negative numbers get a
    leading "-".
    """
    _check_base(base)
    if not isinstance(number, int) or isinstance(number, bool):
        raise ValueError("number must be an integer")
    if number == 0:
        return "0"
    negative = number < 0
    n = abs(number)
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    out = []
    while n > 0:
        out.append(digits[n % base])
        n //= base
    if negative:
        out.append("-")
    out.reverse()
    return "".join(out)


def from_base(text, base):
    """Reverse :func:`to_base`.

    Accepts lower-case and upper-case digits and one optional leading "-".
    Raises ``ValueError`` for invalid base, empty string, a lone "-",
    invalid digits, or any other character (spaces included).
    """
    _check_base(base)
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if text == "":
        raise ValueError("empty string")
    negative = False
    if text[0] == "-":
        negative = True
        text = text[1:]
        if text == "":
            raise ValueError("lone minus sign")
    if text == "":
        raise ValueError("empty string")
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    value = 0
    for ch in text:
        lower = ch.lower()
        d = digits.find(lower)
        if d < 0 or d >= base:
            raise ValueError("invalid digit: %r" % ch)
        value = value * base + d
    if negative:
        value = -value
    return value
